"use strict";
const $=id=>document.getElementById(id);
const providers=[{name:"Mail.tm",base:"https://api.mail.tm"},{name:"Mail.gw",base:"https://api.mail.gw"}];
let domains=[],accounts=[],active=null,nextPage=null,busy=false,refreshing=false,epoch=0;
try {accounts=JSON.parse(sessionStorage.getItem("nuke-mail-v1")||"[]").filter(a=>providers.some(p=>p.base===a.base)&&a.address&&a.password).slice(-10);} catch{}
function save(){try{sessionStorage.setItem("nuke-mail-v1",JSON.stringify(accounts));}catch{$("status").textContent="O navegador não permitiu guardar esta caixa. Mantenha esta página aberta.";}}
const members=x=>Array.isArray(x)?x:(x["hydra:member"]||[]);
async function api(base,path,{data,token}={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const r=await fetch(base+path,{method:data?"POST":"GET",headers:{Accept:"application/json",...(data?{"Content-Type":"application/json"}:{}),...(token?{Authorization:"Bearer "+token}:{})},body:data?JSON.stringify(data):undefined,signal:controller.signal});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(r.status===429?"Muitas solicitações. Aguarde um minuto.":r.status===401?"Acesso à caixa expirou. Tente selecioná-la novamente.":r.status===422?"Endereço recusado. Tente outro nome ou domínio.":"Provedor respondeu com erro "+r.status+".");return j;}catch(e){if(e.name==="AbortError")throw Error("O provedor demorou para responder. Tente novamente.");if(e instanceof TypeError)throw Error("Conexão bloqueada ou indisponível. Tente novamente ou abra o provedor pelo link abaixo.");throw e;}finally{clearTimeout(timer);}}
function renderDomains(){const previous=$("domain").value;$("domain").replaceChildren();const list=domains.filter(d=>!$("edu").checked||/edu/i.test(d.domain));for(const d of list){const o=new Option(d.domain+" · "+d.provider,d.base+"|"+d.domain);$("domain").add(o);}if(!list.length)$("domain").add(new Option($("edu").checked?"Nenhum domínio com edu disponível":"Nenhum domínio disponível",""));else if(list.some(d=>d.base+"|"+d.domain===previous))$("domain").value=previous;$("generate").disabled=busy||!list.length;$("domainNote").textContent=list.length+" domínio(s) disponível(is). A lista pode mudar.";}
async function loadDomains(){$("domainsReload").disabled=true;$("providers").textContent="Consultando provedores…";domains=[];const statuses=await Promise.all(providers.map(async p=>{try{let count=0;for(let page=1;page<=10;page++){const j=await api(p.base,"/domains?page="+page);for(const d of members(j)){if(d.isActive!==false&&!d.isPrivate&&d.domain){domains.push({...d,base:p.base,provider:p.name});count++;}}if(!j["hydra:view"]?.["hydra:next"])break;}return p.name+": "+count+" domínio(s)";}catch{return p.name+": indisponível agora";}}));$("providers").textContent=statuses.join(" · ");renderDomains();$("domainsReload").disabled=false;}
function random(){return Array.from(crypto.getRandomValues(new Uint8Array(8)),x=>x.toString(16).padStart(2,"0")).join("");}
function renderHistory(){$("history").replaceChildren();accounts.forEach((a,i)=>$("history").add(new Option(a.address,String(i))));$("historyLabel").hidden=!accounts.length;$("history").value=String(accounts.indexOf(active));}
async function selectAccount(a){active=a;epoch++;nextPage=null;$("address").value=a.address;$("copy").disabled=false;$("refresh").disabled=false;$("forget").hidden=false;$("messages").replaceChildren();renderHistory();try{if(!a.token){const t=await api(a.base,"/token",{data:{address:a.address,password:a.password}});a.token=t.token;save();}if(active===a)await refresh();}catch(e){$("inboxStatus").textContent=e.message;}}
$("create").addEventListener("submit",async e=>{e.preventDefault();if(busy||!$("domain").value)return;busy=true;renderDomains();$("status").textContent="Criando sua caixa real…";const [base,domain]=$("domain").value.split("|");const prefix=($("name").value||$("category").value).toLowerCase().replace(/[^a-z0-9._-]/g,"").slice(0,30)||"mail";const a={base,address:prefix+"."+random().slice(0,10)+"@"+domain,password:random()+random()};try{await api(base,"/accounts",{data:{address:a.address,password:a.password}});accounts.push(a);accounts=accounts.slice(-10);save();$("status").textContent="Endereço criado. Copie e use para receber mensagens.";await selectAccount(a);}catch(e){$("status").textContent=e.message;}finally{busy=false;renderDomains();}});
async function refresh(page=1){if(!active||!active.token||refreshing)return;refreshing=true;$("refresh").disabled=true;const a=active,version=epoch;$("inboxStatus").textContent="Consultando mensagens…";try{const j=await api(a.base,"/messages?page="+page,{token:a.token});if(version!==epoch)return;const list=members(j);$("messages").replaceChildren();if(!list.length){const empty=document.createElement("div");empty.className="empty";empty.textContent="Ainda não chegou nenhuma mensagem. Atualização automática a cada 12 segundos.";$("messages").append(empty);}for(const m of list){const b=document.createElement("button");b.className="message";const title=document.createElement("strong"),sender=document.createElement("span");title.textContent=m.subject||"Sem assunto";sender.textContent=(m.from?.address||"Remetente desconhecido")+" · "+new Date(m.createdAt).toLocaleString("pt-BR");b.append(title,sender);b.onclick=()=>openMessage(a,m.id);$("messages").append(b);}const next=j["hydra:view"]?.["hydra:next"];nextPage=next?Number(new URL(next,a.base).searchParams.get("page")):null;$("more").hidden=!nextPage;$("inboxStatus").textContent="Atualizado às "+new Date().toLocaleTimeString("pt-BR")+" · "+list.length+" mensagem(ns) nesta página";}catch(e){if(version===epoch)$("inboxStatus").textContent=e.message;}finally{refreshing=false;$("refresh").disabled=!active;}}
async function copy(text){try{await navigator.clipboard.writeText(text);$("status").textContent="Copiado!";}catch{$("address").focus();$("address").select();$("status").textContent="Selecione e copie o endereço acima.";}}
async function openMessage(a,id){try{const m=await api(a.base,"/messages/"+encodeURIComponent(id),{token:a.token});$("subject").textContent=m.subject||"Sem assunto";$("sender").textContent=m.from?.address||"";let text=m.text||"";if(!text&&m.html){const doc=new DOMParser().parseFromString(Array.isArray(m.html)?m.html.join("\n"):m.html,"text/html");doc.querySelectorAll("script,style").forEach(n=>n.remove());text=doc.body.textContent;}$("body").textContent=text||"Mensagem sem conteúdo em texto.";$("codes").replaceChildren();const codes=[...new Set((text+" "+(m.subject||"")).match(/\b\d{4,8}\b/g)||[])].slice(0,8);if(codes.length){const label=document.createElement("p");label.className="small";label.textContent="Possíveis códigos encontrados — confira na mensagem:";$("codes").append(label);codes.forEach(code=>{const b=document.createElement("button");b.textContent=code+" · copiar";b.onclick=()=>copy(code);$("codes").append(b);});}$("reader").showModal();}catch(e){$("inboxStatus").textContent=e.message;}}
$("copy").onclick=()=>copy(active.address);$("refresh").onclick=()=>refresh();$("more").onclick=()=>refresh(nextPage);$("domainsReload").onclick=loadDomains;$("edu").onchange=renderDomains;$("close").onclick=()=>$("reader").close();$("history").onchange=()=>selectAccount(accounts[Number($("history").value)]);$("forget").onclick=()=>{accounts=accounts.filter(a=>a!==active);save();epoch++;active=null;$("address").value="";$("messages").replaceChildren();$("inboxStatus").textContent="Caixa esquecida neste aparelho. Isso não apaga a conta no provedor.";$("copy").disabled=true;$("refresh").disabled=true;$("forget").hidden=true;$("more").hidden=true;renderHistory();if(accounts.length)selectAccount(accounts[accounts.length-1]);};
setInterval(()=>{if(!document.hidden&&active&&!$("reader").open)refresh();},12000);loadDomains();renderHistory();if(accounts.length)selectAccount(accounts[accounts.length-1]);
